window.MG_LAZY_DATA["data/lazy/resources/hpc-v27-064-5ecd5df6a2e43fcf.json"]={sha256:"5ecd5df6a2e43fcf9ad060d7837660252ebca962e352fbae770580eee1650525",value:{"sources":[{"id":"v27-case-50657ae09d83748f","url":"https://nemo-ocean.eu/bibliography/how-to-cite/","title":"NEMO model reference and citation","titleEn":"NEMO model reference and citation","publisher":"NEMO consortium","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v27-064","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v27-064","related":[{"id":"hpc-v27-065","referenceUrls":["https://docs.icon-model.org/2026.04/documentation/atmosphere/atmosphere.html"],"title":"ICON：質量加權示蹤物與網格平均契約","titleEn":"ICON: mass-weighted tracers and grid-average contracts","why":"用兩課的可觀察驗收條件比較模型邊界：常數保持且遮罩一致；平均溫度與總熱量分別命名。","whyEn":"Compare model boundaries using observable acceptance criteria: Constants are preserved and masks agree; mean temperature and total heat content are named separately.","difference":"使用原創合成資料研究「ICON：質量加權示蹤物與網格平均契約」，從物理或資料契約推導計算，並以反例驗證。完成：交付空氣與示蹤物雙帳本、分區重組證據及乾濕基準對照。","differenceEn":"Investigate ICON: mass-weighted tracers and grid-average contracts using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver separate air and tracer mass ledgers, partition-recombination evidence and a reference-convention table that identifies every conversion required before combining datasets.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["計算 10+60 的分子與四的分母；和兩點簡單平均十五比較，指出多數水體位於較暖格。","計算 0.02 與 0.06 kg，再除總空氣質量五；用總示蹤物反推平均作交叉檢查。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Calculate numerator 10+60 and denominator four. Compare the result with the unweighted two-point mean of fifteen and explain why the larger warm cell must contribute more to the volume-weighted statistic.","Compute tracer masses 0.02 and 0.06 kg and divide their sum by five kilograms of air. Reconstruct total tracer mass from the resulting mean to check that no weighting factor disappeared.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v27-074","referenceUrls":["https://sundials.readthedocs.io/en/latest/ida/Mathematics_link.html"],"title":"SUNDIALS IDA：DAE 一致初值與代數約束","titleEn":"SUNDIALS IDA: consistent DAE initial states and algebraic constraints","why":"用兩課的可觀察驗收條件比較模型邊界：常數保持且遮罩一致；平均溫度與總熱量分別命名。","whyEn":"Compare model boundaries using observable acceptance criteria: Constants are preserved and masks agree; mean temperature and total heat content are named separately.","difference":"使用原創合成資料研究「SUNDIALS IDA：DAE 一致初值與代數約束」，從物理或資料契約推導計算，並以反例驗證。完成：交付狀態導數表、逐列殘差、修復比較及一致初值交接紀錄。","differenceEn":"Investigate SUNDIALS IDA: consistent DAE initial states and algebraic constraints using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver a state-derivative table, rowwise residuals, alternative repair comparisons and a consistent-initialization handover explaining which quantities may be adjusted.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["計算 10+60 的分子與四的分母；和兩點簡單平均十五比較，指出多數水體位於較暖格。","代入三個數值，分別得兩列零；以 y1+y2=1 與 ydot1=y2−y1 兩條關係獨立核對。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Calculate numerator 10+60 and denominator four. Compare the result with the unweighted two-point mean of fifteen and explain why the larger warm cell must contribute more to the volume-weighted statistic.","Substitute the three supplied values and obtain zero in both rows. Independently verify the equivalent relations y1+y2=1 and ydot1=y2-y1, making the check independent of the combined norm expression.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-f69294ab4482cd70","url":"https://docs.icon-model.org/2026.04/documentation/atmosphere/atmosphere.html","title":"ICON atmosphere documentation","titleEn":"ICON atmosphere documentation","publisher":"ICON developers","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-97ad0754aed6faaf","url":"https://sundials.readthedocs.io/en/latest/ida/Mathematics_link.html","title":"SUNDIALS IDA mathematics","titleEn":"SUNDIALS IDA mathematics","publisher":"SUNDIALS","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
